//! 快照打包服务: 调用 `webgal-snapshot` 将当前项目打包为精简压缩包。
//!
//! 打包在后台线程执行, 进度通过事件通道 (`tauri::ipc::Channel`) 实时推送给前端。

use std::path::{Path, PathBuf};

use serde::Serialize;
use tauri::ipc::Channel;
use webgal_snapshot::{Error, PackerBuilder, ProgressReporter};

/// 打包进度事件
#[derive(Debug, Clone, Serialize)]
#[serde(rename_all = "camelCase", tag = "type")]
pub enum SnapshotEvent {
    /// 开始扫描
    ScanStart,
    /// 扫描到一个文件
    ScanFile {
        path: String,
        index: usize,
        cumulative_size: u64,
    },
    /// 扫描中遇到错误 (message 为错误描述)
    ScanError { message: String },
    /// 扫描完成
    ScanComplete { count: usize, total_size: u64 },
    /// 开始打包
    PackStart { count: usize, total_size: u64 },
    /// 打包完一个文件
    PackFile {
        path: String,
        index: usize,
        cumulative_size: u64,
        cumulative_compressed_size: u64,
    },
    /// 打包中遇到错误
    PackError { message: String },
    /// 打包完成
    PackComplete { final_size: u64 },
}

/// 打包结果
#[derive(Debug, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct SnapshotResult {
    /// 已打包文件总数
    pub count: usize,
    /// 已打包文件总体积
    pub total_size: u64,
    /// 压缩包总体积
    pub final_size: u64,
    /// 是否被终止 (压缩包未完整生成)
    pub aborted: bool,
    /// 错误描述列表
    pub errors: Vec<String>,
}

/// 进度汇报器: 将打包进度转发到事件通道
struct EventReporter {
    channel: Channel<SnapshotEvent>,
}

impl EventReporter {
    fn new(channel: Channel<SnapshotEvent>) -> Self {
        Self { channel }
    }
}

impl ProgressReporter for EventReporter {
    fn on_scan_start(&self) {
        let _ = self.channel.send(SnapshotEvent::ScanStart);
    }

    fn on_scan_file(&self, path: &Path, index: usize, cumulative_size: u64) {
        let _ = self.channel.send(SnapshotEvent::ScanFile {
            path: path.display().to_string(),
            index,
            cumulative_size,
        });
    }

    fn on_scan_error(&self, error: &Error) -> bool {
        let _ = self.channel.send(SnapshotEvent::ScanError { message: error.to_string() });
        false
    }

    fn on_scan_complete(&self, count: usize, total_size: u64) {
        let _ = self.channel.send(SnapshotEvent::ScanComplete { count, total_size });
    }

    fn on_pack_start(&self, files: &[PathBuf], total_size: u64) {
        let _ = self.channel.send(SnapshotEvent::PackStart { count: files.len(), total_size });
    }

    fn on_pack_file(
        &self,
        path: &Path,
        index: usize,
        cumulative_size: u64,
        cumulative_compressed_size: u64,
    ) {
        let _ = self.channel.send(SnapshotEvent::PackFile {
            path: path.display().to_string(),
            index,
            cumulative_size,
            cumulative_compressed_size,
        });
    }

    fn on_pack_error(&self, error: &Error) -> bool {
        let _ = self.channel.send(SnapshotEvent::PackError { message: error.to_string() });
        false
    }

    fn on_pack_complete(&self, final_size: u64) {
        let _ = self.channel.send(SnapshotEvent::PackComplete { final_size });
    }
}

/// 将 WebGAL 项目打包为快照压缩包
///
/// # Arguments
/// * **source** - 项目根目录.
/// * **destination** - 输出压缩包路径.
/// * **on_event** - 进度事件通道.
#[tauri::command]
pub async fn pack_snapshot(
    source: String,
    destination: String,
    on_event: Channel<SnapshotEvent>,
) -> Result<SnapshotResult, String> {
    tauri::async_runtime::spawn_blocking(move || {
        let reporter = EventReporter::new(on_event);
        let result = PackerBuilder::default()
            .source(source)
            .destination(destination)
            .with_progress(reporter)
            .run();
        SnapshotResult {
            count: result.count,
            total_size: result.total_size,
            final_size: result.final_size,
            aborted: result.aborted,
            errors: result.errors.iter().map(ToString::to_string).collect(),
        }
    })
    .await
    .map_err(|error| error.to_string())
}
